set search_path = naashir, extensions;

-- Naashir MVP schema
-- Design note on access model:
--   * The browser/anon Supabase client is only ever used for organizer auth + the
--     organizer dashboard (authenticated role, RLS-scoped to organizer_id = auth.uid()).
--   * All guest-facing reads/writes (public invite page, RSVP submit, named-guest
--     lookup by token, email send, payment webhook) go through Next.js server route
--     handlers using the SERVICE ROLE key, which bypasses RLS by design. Those routes
--     enforce their own checks (slug match, expiry, etc).
--   * The one rule that must hold no matter which key is used to insert is the guest
--     limit, so it is enforced with a BEFORE INSERT trigger on rsvps (triggers fire for
--     every role, service_role included) rather than relying on RLS alone.

create extension if not exists pgcrypto;

-- ---------- enums ----------
create type event_type as enum ('birthday', 'wedding', 'kids_first_birthday', 'graduation', 'other');
create type rsvp_status as enum ('yes', 'no', 'maybe');
create type payment_provider as enum ('qpay', 'socialpay');
create type payment_status as enum ('pending', 'paid', 'failed');

-- ---------- profiles (mirrors auth.users) ----------
create table naashir.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text,
  created_at timestamptz not null default now()
);

create function naashir.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = naashir
as $$
begin
  insert into naashir.profiles (id, email) values (new.id, new.email);
  return new;
end;
$$;

create trigger naashir_on_auth_user_created
  after insert on auth.users
  for each row execute procedure naashir.handle_new_user();

-- ---------- events ----------
create table naashir.events (
  id uuid primary key default gen_random_uuid(),
  organizer_id uuid not null references naashir.profiles (id) on delete cascade,
  event_type event_type not null,
  name text not null,
  event_date date not null,
  event_time time,
  location text,
  photo_url text,
  description text,
  template_id text not null default 'classic',
  theme jsonb not null default '{}'::jsonb,
  custom_text jsonb not null default '{}'::jsonb,
  video_url text,
  map_link text,
  countdown_enabled boolean not null default false,
  slug text not null unique,
  is_paid boolean not null default false,
  paid_at timestamptz,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '7 days')
);

create index events_organizer_id_idx on naashir.events (organizer_id);
create index events_slug_idx on naashir.events (slug);

-- ---------- named_guests (personalization + optional email invites) ----------
create table naashir.named_guests (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references naashir.events (id) on delete cascade,
  first_name text,
  last_name text,
  email text,
  guest_token text not null unique default encode(gen_random_bytes(9), 'hex'),
  email_sent_at timestamptz,
  created_at timestamptz not null default now()
);

create index named_guests_event_id_idx on naashir.named_guests (event_id);

-- ---------- rsvps (anonymous, device-tracked) ----------
create table naashir.rsvps (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references naashir.events (id) on delete cascade,
  device_guest_id text not null,
  -- Set only when the guest opened a personalized (?to=token) link, so the
  -- dashboard can show "who hasn't answered yet" for the named guest list.
  -- Generic-link responses stay null and are counted in the aggregate totals only.
  named_guest_id uuid references naashir.named_guests (id) on delete set null,
  display_name text,
  status rsvp_status not null,
  party_size int not null default 1 check (party_size >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (event_id, device_guest_id)
);

create index rsvps_event_id_idx on naashir.rsvps (event_id);
create index rsvps_named_guest_id_idx on naashir.rsvps (named_guest_id);

create function naashir.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger rsvps_touch_updated_at
  before update on naashir.rsvps
  for each row execute procedure naashir.touch_updated_at();

-- Enforce the free-plan guest limit at insert time (100 for wedding and graduation;
-- 10 for birthday, kid's 1st birthday and other; unlimited once paid). Only blocks a *new* device_guest_id
-- row -- existing devices updating their own answer go through UPDATE, not INSERT,
-- so they are never blocked by this trigger. Fires for every role (RLS-independent).
create function naashir.enforce_rsvp_limit()
returns trigger
language plpgsql
as $$
declare
  v_event naashir.events%rowtype;
  v_limit int;
  v_count int;
begin
  select * into v_event from naashir.events where id = new.event_id;

  if v_event.is_paid then
    return new;
  end if;

  if v_event.event_type in ('wedding', 'graduation') then
    v_limit := 100;
  else
    v_limit := 10;
  end if;

  select count(*) into v_count from naashir.rsvps where event_id = new.event_id;

  if v_count >= v_limit then
    raise exception 'guest_limit_reached' using errcode = 'P0001';
  end if;

  return new;
end;
$$;

create trigger rsvps_enforce_limit
  before insert on naashir.rsvps
  for each row execute procedure naashir.enforce_rsvp_limit();

-- ---------- payments ----------
create table naashir.payments (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references naashir.events (id) on delete cascade,
  amount integer not null default 999,
  provider payment_provider not null default 'qpay',
  status payment_status not null default 'pending',
  provider_ref text,
  created_at timestamptz not null default now(),
  paid_at timestamptz
);

create index payments_event_id_idx on naashir.payments (event_id);

-- ---------- row level security ----------
-- Everything defaults to owner-only for the authenticated (dashboard) role.
-- No anon policies are defined: guest-facing access goes through server routes
-- using the service role key, which bypasses RLS entirely.
alter table naashir.profiles enable row level security;
alter table naashir.events enable row level security;
alter table naashir.named_guests enable row level security;
alter table naashir.rsvps enable row level security;
alter table naashir.payments enable row level security;

create policy "profiles_select_own" on naashir.profiles
  for select using (auth.uid() = id);

create policy "profiles_update_own" on naashir.profiles
  for update using (auth.uid() = id);

create policy "events_owner_all" on naashir.events
  for all using (auth.uid() = organizer_id) with check (auth.uid() = organizer_id);

create policy "named_guests_owner_all" on naashir.named_guests
  for all using (
    exists (select 1 from naashir.events e where e.id = event_id and e.organizer_id = auth.uid())
  )
  with check (
    exists (select 1 from naashir.events e where e.id = event_id and e.organizer_id = auth.uid())
  );

create policy "rsvps_owner_select" on naashir.rsvps
  for select using (
    exists (select 1 from naashir.events e where e.id = event_id and e.organizer_id = auth.uid())
  );

create policy "payments_owner_select" on naashir.payments
  for select using (
    exists (select 1 from naashir.events e where e.id = event_id and e.organizer_id = auth.uid())
  );
